const b64 = "";
const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
const dsl = new TextDecoder('utf-8').decode(bytes);

const views = ["SystemContext", "Containers"];
const exporters = {
  c4plantuml: (v) => tools.structurizr["export-c4plantuml"]({ dsl, viewKey: v }),
  mermaid: (v) => tools.structurizr["export-mermaid"]({ dsl, viewKey: v }),
  plantuml: (v) => tools.structurizr["export-plantuml"]({ dsl, viewKey: v }),
};
const out = {};
for (const [name, fn] of Object.entries(exporters)) {
  out[name] = {};
  for (const v of views) {
    const r = await fn(v).then(x => ({ ok: true, value: x }), e => ({ ok: false, error: e }));
    out[name][v] = r.ok
      ? (typeof r.value === 'string' ? r.value.slice(0, 200) : r.value)
      : String(r.error).slice(0, 300);
  }
}
return out;

